// legalAcceptUpgrades: what must be recorded when a client accepts a quote.
func legalAcceptUpgrades() map[string]objectUpgrade {
	only := func(f ObjectField) ObjectField { f.Only = "legal"; return f }
	return map[string]objectUpgrade{"quotes": {fields: []ObjectField{
		only(of("acceptedOn", "Client accepted on", "date")),
		only(ofSelect("acceptanceMethod", "Accepted by", opts("signed", "Signed letter", "email", "Email", "whatsapp", "WhatsApp", "in_person", "In person"))),
		only(of("engagementSignedOn", "Engagement letter signed", "date")),
		only(ofSelect("paymentTerms", "Payment terms", opts("full_advance", "Full advance", "advance_balance", "Advance + balance", "stage_wise", "Stage-wise", "per_appearance", "Per appearance"))),
		only(of("advanceAmount", "Advance agreed", "currency")),
	}}}
}

